    const tree = mount(<PressableBox testID="p" onPressIn={onPressIn} onPressOut={onPressOut} style={{ width: 10 }} />);
    const node = () => tree.root.findAll((n) => typeof n.props.onPressIn === 'function' && Array.isArray(n.props.style))[0]!;
    act(() => node().props.onPressIn({}));
    expect(node().props.style[1]).toEqual({ opacity: 0.85 });
    act(() => node().props.onPressOut({}));
    expect(node().props.style[1]).toBeNull();
